const c=$json;
if(c.configured!==true || (c.previewOnly!==true && c.telegramSchemaVerified!==true) || /CONFIGURAR/.test(JSON.stringify(c))) throw new Error('Configuração e identidade Telegram devem ser verificadas antes de executar.');
if(!/^-?\d+$/.test(c.chatId)||!/^\d+$/.test(c.telegramUserId)) throw new Error('IDs Telegram inválidos');
if(!/^https:\/\/[a-z0-9.-]+$/.test(c.publishBaseUrl)) throw new Error('Destino HTTPS inválido');
return [{json:c}];

// Why Code: filtro e validação de URL com allowlist; um único item por execução.
const c=$('CONFIGURACAO').first().json;
const rows=$input.all().filter(i=>i.json.status==='NOVO' && i.json.acao==='PROCESSAR');
if(!rows.length) return [];
const r=rows[0].json;
if(!/^[A-Za-z0-9_-]{1,100}$/.test(String(r.id))) throw new Error('ID inválido');
const raw=String(r.url_fonte).trim();const match=raw.match(/^https:\/\/([a-zA-Z0-9.-]+)(\/[^\s\\]*)?$/);const allowed=c.allowedSourceHosts.split(',').map(x=>x.trim().toLowerCase());
if(!match||!allowed.includes(match[1].toLowerCase()))throw new Error('Fonte fora da allowlist');
return [{json:{...r,url_fonte:raw.replace(/#.*$/,'')}}];

// Why Code: validar contrato JSON da IA antes de qualquer efeito.
const value=(typeof $json.text==='string' ? JSON.parse($json.text) : ($json.text ?? $json));
if(!Array.isArray(value.facts)||value.facts.length<1) throw new Error('Sem fatos verificáveis');
return [{json:{extraction:value}}];

// Why Code: validar contrato JSON da IA antes de qualquer efeito.
const value=(typeof $json.text==='string' ? JSON.parse($json.text) : ($json.text ?? $json));
if(!value.angle||!value.imageSearchQuery) throw new Error('Plano incompleto');
return [{json:{plan:value}}];

// Why Code: validar o contrato e preservar a URL original sem reescrita pela IA.
const value=(typeof $json.text==='string' ? JSON.parse($json.text) : ($json.text ?? $json));
if(!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(value.slug)||value.slug.length>100||!value.title||!Array.isArray(value.sections)||value.sections.length<2) throw new Error('Artigo inválido');
const sourceUrl=$('VALIDAR FONTE').first().json.url;
if(typeof sourceUrl!=='string'||!sourceUrl.startsWith('https://'))throw new Error('Fonte original ausente');
value.sources=[{label:'Money Times',url:sourceUrl}];
return [{json:{article:value}}];

// Why Code: validar contrato JSON da IA antes de qualquer efeito.
const value=(typeof $json.text==='string' ? JSON.parse($json.text) : ($json.text ?? $json));
if(value.approved!==true) throw new Error('Checagem factual reprovada: '+JSON.stringify(value.issues));
return [{json:{factCheck:value}}];

// Why Code: validar contrato JSON da IA antes de qualquer efeito.
const value=(typeof $json.text==='string' ? JSON.parse($json.text) : ($json.text ?? $json));
if(!value.title||!value.description||value.title.length>180||value.description.length>320) throw new Error('SEO inválido');
return [{json:{seo:value}}];

// Why Code: somente metadados reais podem autorizar downloads; IA não concede licença.
const clean=s=>String(s||'').replace(/<[^>]*>/g,'').trim();
const candidates=Object.values($json.query?.pages||{}).flatMap(p=>{
 const i=p.imageinfo?.[0],m=i?.extmetadata||{};if(!i)return [];
 let lic=clean(m.LicenseShortName?.value);const credit=clean(m.Artist?.value);
 if(lic==='CC0 1.0')lic='CC0';
 if(!['CC BY 2.0','CC BY-SA 2.0','CC BY 3.0','CC BY-SA 3.0','CC BY 4.0','CC BY-SA 4.0','CC0','Public domain'].includes(lic)||!credit||i.mime!=='image/jpeg')return [];
 const src=i.url;
 if(typeof src!=='string'||!/^https:\/\/upload\.wikimedia\.org\/[^\s\\]+$/.test(src)||i.width<1000||i.height<500||i.size>5000000)return [];
 return [{pageId:String(p.pageid),title:p.title,url:src,sourceUrl:i.descriptionurl,credit,license:lic,licenseUrl:clean(m.LicenseUrl?.value),description:clean(m.ImageDescription?.value).slice(0,1500)}];
});
if(!candidates.length)throw new Error('Nenhuma fotografia licenciada adequada. Escolha manual necessária.');
return [{json:{candidates}}];

const v=(typeof $json.text==='string' ? JSON.parse($json.text) : ($json.text ?? $json));const c=$('VALIDAR LICENCAS').first().json.candidates.find(i=>i.pageId===String(v.pageId));
if(v.approved!==true||!c||typeof v.alt!=='string'||!v.alt.trim())throw new Error('Curadoria de imagem reprovada');
return [{json:{image:{...c,alt:v.alt,reason:v.reason}}}];

// Why Code: validar assinatura/tamanho binários e construir contrato seguro.
const b=Buffer.from($json.imageBase64,'base64');
if(b.length<10000||b.length>5000000||b[0]!==255||b[1]!==216||b[2]!==255)throw new Error('JPEG inválido ou acima de 5 MB');
const a=JSON.parse(JSON.stringify($('VALIDAR RASCUNHO').first().json.article));
const seo=$('VALIDAR SEO').first().json.seo;const i=$('VALIDAR ESCOLHA IMAGEM').first().json.image;
a.title=seo.title;a.description=seo.description;
a.image={src:'/api/editorial/media/'+a.slug,alt:i.alt,credit:i.credit,license:i.license,sourceUrl:i.sourceUrl,sha256:$json.imageSha256};
a.publishedAt=$now.setZone('America/Sao_Paulo').toISO();
return [{json:{article:a,imageBase64:b.toString('base64'),imageMimeType:'image/jpeg'},binary:$input.first().binary}];

// Why Code: validar contrato JSON da IA antes de qualquer efeito.
const value=(typeof $json.text==='string' ? JSON.parse($json.text) : ($json.text ?? $json));
if(value.approved!==true) throw new Error('Revisão final reprovada: '+JSON.stringify(value.issues));
return [{json:{review:value}}];

// Why Code: hash vincula aprovação a conteúdo imutável; HTML escapado contém a fotografia baixada.
const p=$('MONTAR ARTIGO COM IMAGEM').first().json;
const versionHash=$json.versionHash;
const imageHash=p.article.image.sha256;
const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const a=p.article;
const preview='<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><meta http-equiv="Content-Security-Policy" content="default-src \'none\'; img-src data:; style-src \'unsafe-inline\'"><title>'+esc(a.title)+'</title><style>body{font:18px/1.6 Arial;max-width:820px;margin:32px auto;padding:20px;color:#17201c}img{max-width:100%}h1{line-height:1.2}small{word-break:break-all}</style><h1>'+esc(a.title)+'</h1><p>'+esc(a.description)+'</p><img alt="'+esc(a.image.alt)+'" src="data:image/jpeg;base64,'+p.imageBase64+'"><p>'+esc(a.image.credit)+' · '+esc(a.image.license)+' · Imagem ilustrativa</p><p>'+esc(a.lead)+'</p>'+a.sections.map(s=>'<section><h2>'+esc(s.title)+'</h2>'+s.paragraphs.map(x=>'<p>'+esc(x)+'</p>').join('')+(s.bullets?'<ul>'+s.bullets.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>':'')+'</section>').join('')+'<h2>Fontes</h2>'+a.sources.map(s=>'<p>'+esc(s.label)+' — '+esc(s.url)+'</p>').join('')+'<p>Origem da foto: '+esc(a.image.sourceUrl)+'</p><small>Versão '+versionHash+'<br>Imagem '+imageHash+'</small></html>';
return [{json:{...p,versionHash,imageHash,imageBase64Hash:$json.imageBase64Hash,preview,createdAt:Date.now(),expiresAt:Date.now()+86400000}}];

// Why Code: identidade, validade e conteúdo precisam ser verificáveis antes de publicar.
// ADAPTADOR EXPLÍCITO: confirmar paths do output real de Approve Within Chat na instância.
const r=$('TELEGRAM - APROVAR OU REJEITAR').first().json.data||{};
const userId=r.responder?.id;
const p=$('CONGELAR VERSAO E PREVIEW').first().json,c=$('CONFIGURACAO').first().json;
const approved=r.approved===true && r.responder?.source==='telegram' && String(r.chatId)===c.chatId && String(userId)===c.telegramUserId && Date.now()<p.expiresAt;

if($json.checkedArticleHash!==p.versionHash)throw new Error('Conteúdo alterado após a prévia');
if($json.checkedImageBase64Hash!==p.imageBase64Hash)throw new Error('Imagem alterada após a prévia');
return [{json:{...p,approved,approval:{versionHash:p.versionHash,approvedBy:approved?String(userId):'',approvedAt:new Date().toISOString()},decision:approved?'APROVADO':(r.approved===false?'REJEITADO':'EXPIRADO_OU_NAO_AUTENTICADO')}}];

const p=$('CONGELAR VERSAO E PREVIEW').first().json;
const expected=$('CONFIGURACAO').first().json.publishBaseUrl+'/blog/'+p.article.slug;
if($json.versionHash!==p.versionHash||$json.slug!==p.article.slug||$json.publicUrl!==expected)throw new Error('Recibo não corresponde ao snapshot aprovado');
return [{json:$json}];

const a=$('CONGELAR VERSAO E PREVIEW').first().json.article;
const escaped=a.title.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#x27;'}[c]));
if(typeof $json.publicHtml!=='string'||!$json.publicHtml.includes(escaped))throw new Error('Título da página pública não confirmado');
return [{json:$('VALIDAR RECIBO PUBLICACAO').first().json}];

// Why Code: bloquear publicação até homologação do endpoint e restaurar o pacote aprovado após a escrita no Sheets.
if($('CONFIGURACAO').first().json.publishEnabled!==true)return [];
return [{json:$('VALIDAR APROVACAO HUMANA').first().json}];

// Why Code: o bot atual pertence ao ArIA; preparar a prévia sem registrar um webhook concorrente.
if($('CONFIGURACAO').first().json.previewOnly===true)return [];
return $input.all();

// Why Code: validar e serializar envelope imutável com prova de aprovação; não cabe em um único nó nativo.
const p=$('VALIDAR APROVACAO HUMANA').first().json,c=$('CONFIGURACAO').first().json,row=$('ESCOLHER UM ITEM').first().json;
const evidence=$('TELEGRAM - APROVAR OU REJEITAR').first().json.data||{};
const now=Date.now(),approvedAt=Date.parse(p.approval?.approvedAt);
if(p.approved!==true||p.decision!=='APROVADO'||evidence.approved!==true||evidence.responder?.source!=='telegram'||String(evidence.chatId)!==String(c.chatId)||String(evidence.responder?.id)!==String(c.telegramUserId)||String(p.approval?.approvedBy)!==String(c.telegramUserId))throw new Error('Snapshot exige aprovação Telegram autenticada');
if(!/^[a-f0-9]{64}$/.test(p.versionHash)||p.approval.versionHash!==p.versionHash||!/^[a-f0-9]{64}$/.test(p.imageBase64Hash))throw new Error('Hashes de aprovação inválidos');
if(!Number.isFinite(p.expiresAt)||now>=p.expiresAt||!Number.isFinite(approvedAt)||approvedAt>now+60000||now-approvedAt>=86400000)throw new Error('Aprovação expirada');
if(!Number.isInteger(Number(row.revisao))||Number(row.revisao)<1)throw new Error('Revisão inválida');
const key=String($workflow.id)+':'+String($execution.id)+':'+p.versionHash;
const payload={article:p.article,imageBase64:p.imageBase64,imageMimeType:p.imageMimeType,versionHash:p.versionHash,imageHash:p.imageHash,imageBase64Hash:p.imageBase64Hash,createdAt:p.createdAt,expiresAt:p.expiresAt,approved:true,approval:p.approval,decision:p.decision,approvalEvidence:evidence};
const payloadJson=JSON.stringify(payload);
if(payloadJson.length>8000000)throw new Error('Snapshot excede tamanho permitido');
return [{json:{snapshotKey:key,workflowId:String($workflow.id),executionId:String($execution.id),itemId:String(row.id),revision:Number(row.revisao),versionHash:p.versionHash,imageBase64Hash:p.imageBase64Hash,approvedBy:String(p.approval.approvedBy),approvedAt:p.approval.approvedAt,expiresAt:new Date(p.expiresAt).toISOString(),state:'APPROVED',payloadJson,publicUrl:''}}];
